    fixture.replace("src/spare.spx", "    3", "    4");
    let local = cache.build(&manifest, &fixture.sources()).unwrap();
    assert_eq!(
        work(&local, 1, 3)["invalidated_sources"],
        json!(["src/spare.spx"])
    );
