    assert_eq!(report["work"]["full_cross_file_checks"], true);
    assert_eq!(report["work"]["full_link_and_profile_admission"], true);
    report
}
fn work(build: &ProjectFrontendBuild, parsed: usize, reused: usize) -> Value {
