fn row_loan_sources(fixture: &Fixture, manifest: &ProjectManifest) -> Vec<ProjectFrontendSource> {
    manifest
        .sources()
        .iter()
        .map(|path| ProjectFrontendSource::new(path, &fixture.read(path)).unwrap())
        .collect()
